SELECT MAX(FIRE_SIZE) AS max_size FROM Fires WHERE STATE='AK' AND FIRE_YEAR BETWEEN 2013 AND 2015 AND (
    (substr(DISCOVERY_DATE,1,2)='03' AND substr(DISCOVERY_DATE,4,2) >= '01')
    OR substr(DISCOVERY_DATE,1,2)='04'
    OR (substr(DISCOVERY_DATE,1,2)='05' AND substr(DISCOVERY_DATE,4,2) <= '31')
);
